import{_ as n}from"./chunks/projects-sidebar-colors.DIY830dX.js";import{_ as r,a as i,b as t}from"./chunks/weiteres-beispiel.Chd7zmRi.js";import{_ as a,o as s,c as l,a3 as o}from"./chunks/framework.BlfGB29P.js";const w=JSON.parse('{"title":"Seitenleistenfarben","description":"Eigene Farben und Transparenz für HA-Menüeinträge, direkt in Seitenleiste bearbeiten. HACS und Marketplace, DE/EN/FR.","frontmatter":{"title":"Seitenleistenfarben","description":"Eigene Farben und Transparenz für HA-Menüeinträge, direkt in Seitenleiste bearbeiten. HACS und Marketplace, DE/EN/FR."},"headers":[],"relativePath":"projects/sidebar-colors/index.md","filePath":"projects/sidebar-colors/index.md","lastUpdated":1794057296000}'),d={name:"projects/sidebar-colors/index.md"};function u(h,e,c,g,b,p){return s(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="seitenleistenfarben-sidebar-colors" tabindex="-1">Seitenleistenfarben / Sidebar Colors <a class="header-anchor" href="#seitenleistenfarben-sidebar-colors" aria-label="Permalink to &quot;Seitenleistenfarben / Sidebar Colors&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">HA 2026.11: Selektor korrigiert</p><p>Version <strong>0.1.1</strong> berücksichtigt im nativen Bearbeitungsdialog sowohl <code>ha-md-list-item</code> als auch <code>ha-list-item-button</code>. 27 lokale Tests bestehen, darunter DOM-Regressionen für beide HA-Zeilentypen, Transparenz, Abbrechen, Speichern, erneutes Öffnen und Theme-Rücksetzung. Der entsprechende Manager-Fix wurde auf .177 live geprüft; Sidebar Colors wurde nicht parallel installiert. Bestehende Farben und Speicherschlüssel bleiben erhalten.</p></div><p><a href="/sammlung/ha-2026-11-kompatibilitaet">Prüfumfang, Ergebnisse und offene Punkte</a>.</p><img src="'+n+'" width="80" height="80" alt="Sidebar Colors"><p><strong>0.1.1 · Frontend-Erweiterung · DE / EN / FR · MIT</strong></p><p>Symbol und Beschriftung jedes Eintrags in der Home-Assistant-Seitenleiste individuell einfärben. Das neue Farbfeld sitzt direkt im vorhandenen Dialog <strong>„Seitenleiste bearbeiten“</strong>, zwischen Name und Auge. Sichtbarkeit und Reihenfolge bleiben über die gewohnten Bedienelemente einstellbar.</p><p><a href="https://github.com/rockbaer2007/ha-sidebar-colors" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://github.com/rockbaer2007/ha-sidebar-colors/releases/latest" target="_blank" rel="noreferrer">Download / Releases</a> · <a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=ha-sidebar-colors&amp;category=plugin" target="_blank" rel="noreferrer">In HACS öffnen</a></p><h2 id="farbwahler" tabindex="-1">Farbwähler <a class="header-anchor" href="#farbwahler" aria-label="Permalink to &quot;Farbwähler&quot;">​</a></h2><p>Farbfläche für Sättigung und Helligkeit, Farbtonregler, HEX-Eingabe und Deckkraft mit Live-Vorschau. Das Schachbrett steht für Transparenz. <strong>„Übernehmen“</strong> schließt den Farbwähler; erst <strong>„Speichern“</strong> im HA-Dialog sichert dauerhaft. <strong>„Abbrechen“</strong> verwirft den jeweiligen Farbentwurf. <strong>„Theme-Farbe“</strong> entfernt die eigene Farbe des Eintrags.</p><p><img src="'+r+'" alt="Farbwähler für ATLAS mit 70 Prozent Deckkraft"></p><h2 id="beispiele-des-nutzers" tabindex="-1">Beispiele des Nutzers <a class="header-anchor" href="#beispiele-des-nutzers" aria-label="Permalink to &quot;Beispiele des Nutzers&quot;">​</a></h2><p>Die Ergebnisbilder zeigen individuell gewählte Farben für Symbole und Texte. Gleiche Anzeigenamen bleiben über unterschiedliche Panel-Pfade getrennt. Es wird keine feste Farbpalette erzwungen.</p><div class="sidebar-color-examples"><figure><a href="/images/sidebar-colors/beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+i+'" alt="Farbige Seitenleiste mit Übersicht, ATLAS und HACS"></a><figcaption>Erstes Ergebnis mit frei gewählten Farben.</figcaption></figure><figure><a href="/images/sidebar-colors/weiteres-beispiel.png" target="_blank" rel="noopener noreferrer"><img src="'+t+`" alt="Weiteres Beispiel mit ATLAS-Werkzeugen und Zigbee2MQTT"></a><figcaption>Weitere Zusammenstellung mit ATLAS-Werkzeugen.</figcaption></figure></div><h2 id="voraussetzungen-und-prufstand" tabindex="-1">Voraussetzungen und Prüfstand <a class="header-anchor" href="#voraussetzungen-und-prufstand" aria-label="Permalink to &quot;Voraussetzungen und Prüfstand&quot;">​</a></h2><p>Vorgesehene Mindestversion: <strong>Home Assistant Core 2026.10.3</strong>. Real geprüft auf <strong>2026.10.4</strong>: Farbauswahl, 70 % und 0 % Deckkraft, Vorschau, Speichern/Abbrechen, Neuladen, Theme-Rücksetzen, Zweittab-Synchronisierung sowie vorhandene Augen- und Sortierfunktionen. Der Nutzer bestätigt das Ergebnis. Die frühere Testfarbe wurde entfernt, seine eigenen Farben wurden erhalten.</p><p>Die Mindestversion beruht auf den vorhandenen Schnittstellen; ein separater Live-Test unter 2026.10.3 wird nicht behauptet. Marketplace ab <strong>2026.11</strong> verwendet das gleiche HACS-kompatible Paketformat; dafür liegt noch kein eigener Laufzeittest vor. <a href="https://contributors.home-assistant.io/marketplace/how-it-works/" target="_blank" rel="noreferrer">Offizielle Marketplace-Beschreibung</a></p><h2 id="hacs-marketplace-installieren" tabindex="-1">HACS / Marketplace installieren <a class="header-anchor" href="#hacs-marketplace-installieren" aria-label="Permalink to &quot;HACS / Marketplace installieren&quot;">​</a></h2><p>Vorher ein vollständiges HA-Backup erstellen. Es handelt sich um ein <strong>Frontend-Plugin</strong>, keine Supervisor-App und keine Karte zum Einfügen. Das eigene Repo ist zunächst als benutzerdefiniertes Repository verfügbar; eine Veröffentlichung ist keine automatische Aufnahme in den Standardkatalog.</p><ol><li>In HACS über <strong>Benutzerdefinierte Repositories</strong> <code>https://github.com/rockbaer2007/ha-sidebar-colors</code> hinzufügen, Kategorie <strong>Dashboard</strong> (<code>plugin</code>), anschließend <strong>Sidebar Colors</strong> herunterladen.</li><li>Ab 2026.11 über <strong>Einstellungen → Marketplace</strong> den entsprechenden Weg für benutzerdefinierte Repositories verwenden. Marketplace übernimmt die HACS-Einstellungen; ein eigenes Migrationsformat ist nicht erforderlich.</li><li>Im vorhandenen <code>frontend:</code>-Abschnitt ergänzen. Vorhandene Themes und weitere Module beibehalten; keinen zweiten Block anlegen:</li></ol><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  extra_module_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/hacsfiles/ha-sidebar-colors/ha-sidebar-colors.js</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol start="4"><li>Konfiguration prüfen, HA neu starten und Browser neu laden. Nur eine Dashboard-Ressource reicht nicht, wenn zuerst eine andere HA-Seite geöffnet wird. Der Moduleintrag lädt die Erweiterung auch dort.</li><li>Den Kopf <strong>Home Assistant</strong> in der Seitenleiste länger gedrückt halten und ein Farbfeld anklicken.</li></ol><h2 id="manuell-installieren-oder-umsteigen" tabindex="-1">Manuell installieren oder umsteigen <a class="header-anchor" href="#manuell-installieren-oder-umsteigen" aria-label="Permalink to &quot;Manuell installieren oder umsteigen&quot;">​</a></h2><p>Die einzelne Datei <code>ha-sidebar-colors.js</code> aus dem Release nach <code>/config/www/ha-sidebar-colors.js</code> kopieren und stattdessen <code>/local/ha-sidebar-colors.js</code> als Modul verwenden. Das Release-ZIP enthält dieselbe Datei, Lizenz und Dokumentation. Nicht beide Installationswege gleichzeitig laden.</p><p>Beim älteren Drei-Dateien-Prototyp den Eintrag <code>/local/ugso-sidebar-colors/0.1.0/sidebar-colors.js</code> durch den neuen Pfad ersetzen, HA neu starten und den Browser neu laden. Die Farbablage bleibt gleich; alte Dateien können als Sicherung erhalten bleiben.</p><h2 id="einstellungen-erhalten-und-aktualisieren" tabindex="-1">Einstellungen erhalten und aktualisieren <a class="header-anchor" href="#einstellungen-erhalten-und-aktualisieren" aria-label="Permalink to &quot;Einstellungen erhalten und aktualisieren&quot;">​</a></h2><p>Farben werden pro HA-Benutzer im eigenen Schlüssel <code>ugso_sidebar_colors_v1</code> gespeichert und auf Geräten mit geladener Erweiterung synchronisiert. Panel-Pfade statt Namen verhindern Verwechslungen. Nur Farben zu speichern überschreibt weder native Reihenfolge noch ausgeblendete Einträge oder Theme. Dashboard-Konfigurationen und Berechtigungen werden nicht verändert.</p><p>Vor dem Farbspeichern wird ein vorheriger Stand der Farben und Sidebar-Präferenzen lokal unter <code>ugso-sidebar-colors-backup:&lt;user-id&gt;</code> gesichert. Das ersetzt kein HA-Vollbackup. Ist der Browserspeicher voll oder gesperrt, wird nicht gespeichert. Keine neuen Zugangsdaten, externen Skripte oder Cloud-Übersetzungen erforderlich.</p><p>Updates über dasselbe HACS-/Marketplace-Repo installieren, Modulpfad erhalten und Browser neu laden. Für den Rückbau nur den eigenen Moduleintrag entfernen, HA neu starten und Browser neu laden. Die Theme-Farben kehren zurück; native Einstellungen bleiben erhalten.</p><h2 id="grenzen" tabindex="-1">Grenzen <a class="header-anchor" href="#grenzen" aria-label="Permalink to &quot;Grenzen&quot;">​</a></h2><p>Die Erweiterung nutzt interne HA-Dialogmethoden und muss nach Frontend-Updates erneut geprüft werden. Konflikte oder unklare Speicherbestätigungen halten den Entwurf offen; keine blinden Schreibwiederholungen. Es gibt keine serverseitige atomare Vergleich-und-Speichern-Funktion für diesen Benutzerspeicher. Farb- und native Reihenfolgeänderungen sind getrennte Vorgänge mit geprüftem bestmöglichem Rücksetzen bei Fehlern.</p><p>Bei 0 % Deckkraft können Symbol und Text unsichtbar sein, das Farbfeld bleibt erreichbar. Auswahlhintergrund, Titel und Zugriffsschutz bleiben unverändert. Ausfall-/Konflikttests wurden lokal simuliert; kein echter Handy-/Tablettest oder Netzabbruch unter Marketplace behauptet. <a href="https://github.com/rockbaer2007/ha-sidebar-colors/blob/main/docs/TESTING.md" target="_blank" rel="noreferrer">Prüfdetails und Quellcode</a>.</p>`,31)])])}const S=a(d,[["render",u]]);export{w as __pageData,S as default};
